// WF-SOCIAL-05 — Publication via APIs natives (remplace Blotato).
// SECURITE: double garde. Rien n'est publie tant que Config.PUBLISH_ENABLED != 'true'
// ET que le token de la plateforme est present.
// Audit 2026-07-20: en_publication -> publié (fin du cul-de-sac) ; skip permanent -> Status='échec'+Erreurs
// (fin des boucles silencieuses) ; SEULE la garde PUBLISH_ENABLED reste silencieuse (pause volontaire).
const posts = $('Aplatir — Lire validés').all().map(i => i.json)
  // Fenetre de 15 min : remplace IS_AFTER(NOW(), DATEADD(...,-15,'minutes'))
  // d'Airtable, sans equivalent dans le filtre `where` de NocoDB.
  .filter(p => { const d = p.Date_Publication_Prevue;
                 return !d || new Date(d).getTime() - 15*60*1000 <= Date.now(); });
const cfgRows = $('Aplatir — Lire Config').all().map(i => i.json);
const cfg = {};
for (const r of cfgRows) { if (r && r.Cle != null) cfg[r.Cle] = r.Valeur; }
const PUBLISH_ENABLED = String(cfg.PUBLISH_ENABLED || '').toLowerCase() === 'true';
const http = this.helpers.httpRequest.bind(this);
const isVideo = (u) => /\.(mp4|mov|m4v|webm)(\?|$)/i.test(u || '');
const out = [];

async function publishOne(post) {
  const net = String(post.Reseau || '').toLowerCase();
  const text = (post.Texte || '') + (post.Hashtags ? '\n\n' + post.Hashtags : '');
  let media = [];
  try { media = JSON.parse(post.Visuels_URLs || '[]'); } catch (e) {}
  const media0 = media[0];
  // garde PUBLISH_ENABLED : silencieux, laisse le post en 'validé'
  const silent = (reason) => ({ _silent: true, id: post.id, platform: net, reason });
  // echec permanent : sort le post de la file, ecrit Status=échec + Erreurs
  const fail = (reason) => ({ id: post.id, platform: net, Status: 'échec', Blotato_PostSubmissionID: '', Blotato_PublicUrl: null, native_details: reason, Erreurs: String(reason).slice(0,500), log_status: 'skipped' });
  // Correction 2026-10-29 : 'publié' UNIQUEMENT si la plateforme a renvoyé un id réel (plus de repli sur l'id de conteneur).
  const ok = (platform, pid, details, url) => (pid
    ? { id: post.id, platform, Status: 'publié', Blotato_PostSubmissionID: String(pid), Blotato_PublicUrl: url || null, native_details: details + (url ? ' · ' + url : ''), Erreurs: '', log_status: 'success' }
    : fail(platform + ': la plateforme n\'a renvoyé aucun id de publication (' + details + ')'));
  const metaPermalink = async (objId, field, TOK) => {
    try { const r = await http({ method: 'GET', url: 'https://graph.facebook.com/v21.0/' + objId, qs: { fields: field, access_token: TOK }, json: true }); return (r && r[field]) || null; }
    catch (e) { console.log('permalien introuvable', objId, e && e.message); return null; }
  };

  if (!PUBLISH_ENABLED) return silent('PUBLISH_ENABLED != true (dry-run, garde R1)');

  // ── Stories (29/10/2026) : Format_Post = story. Pas de légende ni de lien cliquable via l'API ;
  // le visuel 9:16 porte tout. Avant ce bloc, une story « validé » partait en post de FIL.
  // Doc Graph v21 vérifiée le 29/10 : IG = conteneur media_type=STORIES → status_code FINISHED →
  // media_publish ; FB Page = /photos published=false → photo_id → /photo_stories (renvoie post_id).
  if (String(post.Format_Post || '').toLowerCase() === 'story') {
    if (!media0) return fail('story: aucun visuel (Visuels_URLs vide)');
    const pause = (ms) => (typeof setTimeout === 'function' ? new Promise((r) => setTimeout(r, ms)) : Promise.resolve());
    if (net === 'ig' || net === 'instagram') {
      const IG = cfg.IG_USER_ID, TOK = cfg.META_TOKEN;
      if (!IG || !TOK) return fail('IG_USER_ID/META_TOKEN manquant');
      const base = 'https://graph.facebook.com/v21.0/' + IG;
      const video = isVideo(media0);
      const c = await http({ method: 'POST', url: base + '/media', body: Object.assign({ media_type: 'STORIES', access_token: TOK }, video ? { video_url: media0 } : { image_url: media0 }), json: true });
      if (!c || !c.id) return fail('IG story: conteneur non cree');
      // Meta traite le média de façon asynchrone : on attend FINISHED (image : quelques secondes).
      let st = '', tries = video ? 24 : 10;
      for (let k = 0; k < tries; k++) {
        const s = await http({ method: 'GET', url: 'https://graph.facebook.com/v21.0/' + c.id, qs: { fields: 'status_code,status', access_token: TOK }, json: true });
        st = (s && s.status_code) || '';
        if (st === 'FINISHED' || st === 'ERROR' || st === 'EXPIRED' || st === 'PUBLISHED') { if (st === 'ERROR') st += ' (' + ((s && s.status) || '') + ')'; break; }
        await pause(video ? 5000 : 3000);
      }
      if (st !== 'FINISHED') return fail('IG story: conteneur ' + c.id + ' non pret (status_code=' + (st || 'inconnu') + ')');
      const pub = await http({ method: 'POST', url: base + '/media_publish', body: { creation_id: c.id, access_token: TOK }, json: true });
      if (!pub || !pub.id) return fail('IG story: media_publish sans id (conteneur ' + c.id + ')');
      return ok('instagram', pub.id, 'IG story ' + pub.id, await metaPermalink(pub.id, 'permalink', TOK));
    }
    if (net === 'fb' || net === 'facebook') {
      const PAGE = cfg.FB_PAGE_ID, TOK = cfg.META_TOKEN;
      if (!PAGE || !TOK) return fail('FB_PAGE_ID/META_TOKEN manquant');
      if (isVideo(media0)) return fail('FB story video non geree (televersement /video_stories en 3 phases a coder)');
      const base = 'https://graph.facebook.com/v21.0/' + PAGE;
      const ph = await http({ method: 'POST', url: base + '/photos', body: { url: media0, published: false, access_token: TOK }, json: true });
      if (!ph || !ph.id) return fail('FB story: photo non televersee');
      const st = await http({ method: 'POST', url: base + '/photo_stories', body: { photo_id: ph.id, access_token: TOK }, json: true });
      const sid = st && st.success !== false && st.post_id;
      if (!sid) return fail('FB story: photo_stories sans post_id (photo ' + ph.id + ')');
      return ok('facebook', sid, 'FB story ' + sid, await metaPermalink(sid, 'permalink_url', TOK));
    }
    return fail('story: reseau non gere (' + net + ') — seuls ig et fb publient des stories');
  }
  if (!text || !text.trim()) return fail('Texte vide — rien a publier');

  if (net === 'ig' || net === 'instagram') {
    const IG = cfg.IG_USER_ID, TOK = cfg.META_TOKEN;
    if (!IG || !TOK) return fail('IG_USER_ID/META_TOKEN manquant');
    const base = 'https://graph.facebook.com/v21.0/' + IG;
    const images = media.filter((u) => u && !isVideo(u));
    if (images.length > 1) {
      const children = [];
      for (const img of images.slice(0, 10)) {
        const cc = await http({ method: 'POST', url: base + '/media', body: { image_url: img, is_carousel_item: true, access_token: TOK }, json: true });
        if (cc && cc.id) children.push(cc.id);
      }
      if (children.length < 2) return fail('IG carrousel: moins de 2 conteneurs crees');
      const car = await http({ method: 'POST', url: base + '/media', body: { media_type: 'CAROUSEL', children, caption: text, access_token: TOK }, json: true });
      if (!car || !car.id) return fail('IG carrousel: conteneur non cree');
      const pub = await http({ method: 'POST', url: base + '/media_publish', body: { creation_id: car.id, access_token: TOK }, json: true });
      if (!pub || !pub.id) return fail('IG carrousel: media_publish sans id (conteneur ' + car.id + ')');
      return ok('instagram', pub.id, 'IG carrousel ' + children.length + ' · ' + pub.id, await metaPermalink(pub.id, 'permalink', TOK));
    }
    if (!media0) return fail('IG requiert un media (Visuels_URLs vide)');
    const createBody = isVideo(media0)
      ? { media_type: 'REELS', video_url: media0, caption: text, access_token: TOK }
      : { image_url: media0, caption: text, access_token: TOK };
    const c = await http({ method: 'POST', url: base + '/media', body: createBody, json: true });
    const creationId = c && c.id;
    if (!creationId) return fail('IG: conteneur non cree');
    const pub = await http({ method: 'POST', url: base + '/media_publish', body: { creation_id: creationId, access_token: TOK }, json: true });
    if (!pub || !pub.id) return fail('IG: media_publish sans id (conteneur ' + creationId + ')');
    return ok('instagram', pub.id, 'IG ' + pub.id, await metaPermalink(pub.id, 'permalink', TOK));
  }

  if (net === 'fb' || net === 'facebook') {
    const PAGE = cfg.FB_PAGE_ID, TOK = cfg.META_TOKEN;
    if (!PAGE || !TOK) return fail('FB_PAGE_ID/META_TOKEN manquant');
    const base = 'https://graph.facebook.com/v21.0/' + PAGE;
    let res;
    if (media0 && !isVideo(media0)) res = await http({ method: 'POST', url: base + '/photos', body: { url: media0, caption: text, access_token: TOK }, json: true });
    else res = await http({ method: 'POST', url: base + '/feed', body: { message: text, access_token: TOK }, json: true });
    const fbPost = res && (res.post_id || res.id);
    if (!fbPost) return fail('FB: aucun id renvoye');
    return ok('facebook', fbPost, 'FB ' + fbPost, await metaPermalink(fbPost, 'permalink_url', TOK));
  }

  if (net === 'tiktok') {
    const TOK = cfg.TIKTOK_TOKEN;
    if (!TOK) return fail('TIKTOK_TOKEN manquant');
    if (!media0 || !isVideo(media0)) return fail('TikTok requiert une video (Visuels_URLs)');
    const res = await http({ method: 'POST', url: 'https://open.tiktokapis.com/v2/post/publish/video/init/',
      headers: { Authorization: 'Bearer ' + TOK, 'Content-Type': 'application/json; charset=UTF-8' },
      body: { post_info: { title: (post.Titre || text || 'Max-Morrys').substring(0,150), privacy_level: 'PUBLIC_TO_EVERYONE', disable_comment: false }, source_info: { source: 'PULL_FROM_URL', video_url: media0 } }, json: true });
    const pid = res && res.data ? res.data.publish_id : undefined;
    return ok('tiktok', pid, 'TikTok ' + pid);
  }

  if (net === 'linkedin') {
    const TOK = cfg.LINKEDIN_TOKEN, URN = cfg.LINKEDIN_AUTHOR_URN;
    if (!TOK || !URN) return fail('LINKEDIN_TOKEN/LINKEDIN_AUTHOR_URN manquant');
    const res = await http({ method: 'POST', url: 'https://api.linkedin.com/rest/posts',
      headers: { Authorization: 'Bearer ' + TOK, 'LinkedIn-Version': '202401', 'X-Restli-Protocol-Version': '2.0.0', 'Content-Type': 'application/json' },
      body: { author: URN, commentary: text, visibility: 'PUBLIC', distribution: { feedDistribution: 'MAIN_FEED', targetEntities: [], thirdPartyDistributionChannels: [] }, lifecycleState: 'PUBLISHED', isReshareDisabledByAuthor: false },
      json: true, returnFullResponse: true });
    const pid = (res.headers && (res.headers['x-restli-id'] || res.headers['x-linkedin-id'])) || null;
    return ok('linkedin', pid, 'LinkedIn ' + pid, pid ? 'https://www.linkedin.com/feed/update/' + pid : null);
  }

  if (net === 'x' || net === 'twitter') {
  const ckey = cfg.X_API_KEY, csec = cfg.X_API_SECRET, atok = cfg.X_ACCESS_TOKEN, asec = cfg.X_ACCESS_SECRET;
  if (!ckey || !csec || !atok || !asec) return fail('X OAuth1 tokens manquants (X_API_KEY/X_API_SECRET/X_ACCESS_TOKEN/X_ACCESS_SECRET)');
  const crypto = require('crypto');
  const enc = (s) => encodeURIComponent(s).replace(/[!*'()]/g, (c) => '%' + c.charCodeAt(0).toString(16).toUpperCase());
  const postTweet = async (tweetText, replyTo) => {
    const url = 'https://api.twitter.com/2/tweets';
    const oauth = { oauth_consumer_key: ckey, oauth_nonce: crypto.randomBytes(16).toString('hex'), oauth_signature_method: 'HMAC-SHA1', oauth_timestamp: Math.floor(Date.now() / 1000).toString(), oauth_token: atok, oauth_version: '1.0' };
    const paramStr = Object.keys(oauth).sort().map((k) => enc(k) + '=' + enc(oauth[k])).join('&');
    const baseStr = ['POST', enc(url), enc(paramStr)].join('&');
    oauth.oauth_signature = crypto.createHmac('sha1', enc(csec) + '&' + enc(asec)).update(baseStr).digest('base64');
    const authHeader = 'OAuth ' + Object.keys(oauth).sort().map((k) => enc(k) + '="' + enc(oauth[k]) + '"').join(', ');
    const body = { text: tweetText };
    if (replyTo) body.reply = { in_reply_to_tweet_id: replyTo };
    const res = await http({ method: 'POST', url, headers: { Authorization: authHeader, 'Content-Type': 'application/json' }, body, json: true });
    return res && res.data ? res.data.id : undefined;
  };
  const raw = String(text || '');
  let parts = /(^|\n)\s*\d+\/\s/.test(raw)
    ? raw.split(/\n(?=\s*\d+\/\s)/).map((s) => s.trim()).filter(Boolean)
    : raw.split(/\n\n+/).map((s) => s.trim()).filter(Boolean);
  parts = parts.map((s) => (s.length > 280 ? s.slice(0, 277) + '…' : s));
  if (!parts.length) parts = [raw.slice(0, 280)];
  let lastId, count = 0;
  for (const tw of parts) {
    const id = await postTweet(tw, lastId);
    if (!id) { if (count === 0) return fail('X: publication echouee'); break; }
    lastId = id; count++;
  }
  return ok('x', lastId, 'X thread ' + count + '/' + parts.length, lastId ? 'https://x.com/i/web/status/' + lastId : null);
}

  if (net === 'youtube') {
    return fail('YouTube = noeud n8n natif requis (upload resumable videos.insert)');
  }
  return fail('reseau inconnu: ' + net);
}

for (const post of posts) {
  try {
    const r = await publishOne(post);
    if (r && r._silent) { console.log('SILENT-SKIP', JSON.stringify(r)); continue; }
    if (r) out.push({ json: r });
  } catch (e) {
    const msg = (e && e.message) ? String(e.message) : 'inconnue';
    console.log('ERREUR publication', post && post.id, msg);
    out.push({ json: { id: post.id, platform: 'error', Status: 'échec', Blotato_PostSubmissionID: '', native_details: 'exception: ' + msg, Erreurs: ('exception: ' + msg).slice(0,500), log_status: 'error' } });
  }
}
return out;
